#include <stdio.h>
#include <stdlib.h>

#define NUM_VERTICES 8

int adj[NUM_VERTICES][NUM_VERTICES];
int color[NUM_VERTICES];
char found_cycle = 0;

void dfs(int vertex) {
    if (found_cycle) return;
    color[vertex] = 1;
    for (int i = 0; i < NUM_VERTICES; i++) {
        if (adj[vertex][i] && color[i] == 0) {
            dfs(i);
        } else if (adj[vertex][i] && color[i] == 1) {
            found_cycle = 1;
        }
    }
    color[vertex] = 2;
}

int main(int argc, char **argv) {
    if (argc < 3) {
        printf("INVALID_INPUT\n");
        return 1;
    }
    for (int i = 0; i < NUM_VERTICES; i++) {
        for (int j = 0; j < NUM_VERTICES; j++) {
            adj[i][j] = 0;
        }
    }
    for (int i = 1; i < argc; i += 2) {
        int u = atoi(argv[i]);
        int v = atoi(argv[i + 1]);
        adj[u][v] = 1;
    }
    for (int i = 0; i < NUM_VERTICES; i++) {
        color[i] = 0;
    }
    for (int i = 0; i < NUM_VERTICES; i++) {
        if (color[i] == 0) {
            dfs(i);
        }
    }
    if (found_cycle) {
        printf("CYCLE\n");
    } else {
        printf("ACYCLIC\n");
    }
    return 0;
}
